function total(values: readonly number[]): number {
  return values.reduce((a, b) => a + b, 0);
}

const mutable = [1, 2, 3];
total(mutable); // OK — mutable assignable to readonly
// values.push(4); // error inside total

type Row = { cells: string[] };

function freezeRows(rows: readonly Row[]): void {
  rows[0].cells.push('extra'); // compiles — nested array mutable
}

const data: Row[] = [{ cells: ['a'] }];
freezeRows(data);

function logKeys(map: ReadonlyMap<string, number>): void {
  for (const [k, v] of map) console.log(k, v);
  // map.set('x', 1); // error — no set on ReadonlyMap
}

const scores = new Map([['ada', 95]]);
logKeys(scores);

const config: readonly string[] = ['prod', 'staging'];

function mutate(xs: string[]) { xs.push('dev'); }

mutate(config as string[]); // bypasses compile check — runtime mutation
